// Dos formas de esperar 300 ms. Un «latido» de la app cuenta cada 50 ms si el hilo está libre.
let latidos = 0;
const reloj = setInterval(() => latidos++, 50);

function esperarBloqueando(ms) {            // el hilo se queda dando vueltas: nadie más corre
  const fin = performance.now() + ms;
  while (performance.now() < fin) { /* ocupado */ }
}
const esperarLibre = ms => new Promise(resolver => setTimeout(resolver, ms)); // deja un aviso y suelta el hilo

esperarBloqueando(300);
console.log("Bloqueando 300 ms → latidos que hubo:", latidos);

latidos = 0;
await esperarLibre(300);
console.log("Con promesa 300 ms → latidos que hubo:", latidos);
clearInterval(reloj);

// Tres pasos que dependen uno del otro, con callbacks «error primero» (error, resultado)
function buscarCamioneta(id, cb) {
  setTimeout(() => (id === "AB123CD" ? cb(null, { id, chofer: "Marta" }) : cb(new Error("camioneta inexistente"))), 20);
}
function buscarRuta(camioneta, cb) {
  setTimeout(() => cb(null, { ruta: "Ruta 5", chofer: camioneta.chofer }), 20);
}
function buscarParadas(ruta, cb) {
  setTimeout(() => cb(null, ["Luján", "Mercedes", "Chivilcoy"]), 20);
}

function paradasDe(id, cb) {
  buscarCamioneta(id, (e1, camioneta) => {
    if (e1) return cb(e1);
    buscarRuta(camioneta, (e2, ruta) => {
      if (e2) return cb(e2);
      buscarParadas(ruta, (e3, paradas) => {
        if (e3) return cb(e3);
        cb(null, `${ruta.chofer} hace ${ruta.ruta}: ${paradas.join(" → ")}`);
      });
    });
  });
}

paradasDe("AB123CD", (error, texto) => console.log(error ? "falló: " + error.message : texto));
paradasDe("XX000XX", (error, texto) => console.log(error ? "falló: " + error.message : texto));
await new Promise(r => setTimeout(r, 200)); // damos tiempo a que terminen

// Los mismos tres pasos, ahora devolviendo promesas
const esperar = ms => new Promise(r => setTimeout(r, ms));
const buscarCamioneta = async id => { await esperar(20); if (id !== "AB123CD") throw new Error("camioneta inexistente"); return { id, chofer: "Marta" }; };
const buscarRuta = camioneta => esperar(20).then(() => ({ ruta: "Ruta 5", chofer: camioneta.chofer }));
const buscarParadas = ruta => esperar(20).then(() => ["Luján", "Mercedes", "Chivilcoy"]);

function paradasDe(id) {
  return buscarCamioneta(id)
    .then(camioneta => buscarRuta(camioneta))              // devolver la promesa: la cadena espera
    .then(ruta => buscarParadas(ruta).then(p => `${ruta.chofer} hace ${ruta.ruta}: ${p.join(" → ")}`));
}

const a = paradasDe("AB123CD").then(console.log).catch(e => console.log("falló: " + e.message));
const b = paradasDe("XX000XX").then(console.log).catch(e => console.log("falló: " + e.message));
console.log("las dos promesas ya existen; ninguna terminó todavía");
await Promise.all([a, b]);

// Los mismos tres pasos con async/await: se lee de arriba hacia abajo
const esperar = ms => new Promise(r => setTimeout(r, ms));
async function buscarCamioneta(id) { await esperar(20); if (id !== "AB123CD") throw new Error("camioneta inexistente"); return { id, chofer: "Marta" }; }
async function buscarRuta(camioneta) { await esperar(20); return { ruta: "Ruta 5", chofer: camioneta.chofer }; }
async function buscarParadas(ruta) { await esperar(20); return ["Luján", "Mercedes", "Chivilcoy"]; }

async function paradasDe(id) {
  const camioneta = await buscarCamioneta(id);
  const ruta = await buscarRuta(camioneta);
  const paradas = await buscarParadas(ruta);
  return `${ruta.chofer} hace ${ruta.ruta}: ${paradas.join(" → ")}`;
}

for (const id of ["AB123CD", "XX000XX"]) {
  try {
    console.log(await paradasDe(id));
  } catch (error) {                       // un solo catch para los tres pasos
    console.log("falló: " + error.message);
  }
}

