// Un timer de 10 ms que llega tarde porque el hilo está ocupado
const pedido = performance.now();
setTimeout(() => {
  const demora = Math.round((performance.now() - pedido) / 50) * 50; // redondeo a 50 ms para que el número sea legible
  console.log(`pedí 10 ms; llegó después de unos ${demora} ms`);
}, 10);

