// Consultar el estado de tres camionetas «a la vez»
const esperar = ms => new Promise(r => setTimeout(r, ms));
const estado = (patente, ms, falla = false) =>
  esperar(ms).then(() => { if (falla) throw new Error(patente + " sin señal"); return patente + " OK"; });
const pedidos = () => [estado("AB123CD", 100), estado("EF456GH", 200, true), estado("IJ789KL", 300)];
const redondeo = t => Math.round(t / 50) * 50;                    // a múltiplos de 50 ms
let t0;
const reloj = () => redondeo(performance.now() - t0) + " ms";

t0 = performance.now();
try { await Promise.all(pedidos()); }
catch (e) { console.log(`all → rechaza con «${e.message}» a los ${reloj()}`); }

t0 = performance.now();
const todos = await Promise.allSettled(pedidos());
console.log(`allSettled → espera a todas (${reloj()}):`);
for (const r of todos) console.log("  ", r.status, r.value ?? r.reason.message);

t0 = performance.now();
console.log(`race → ${await Promise.race(pedidos())} a los ${reloj()}`);

t0 = performance.now();
console.log(`any → ${await Promise.any(pedidos())} a los ${reloj()}`);

// Tres pedidos uno detrás de otro (con await en un for): los tiempos se suman
t0 = performance.now();
for (const ms of [100, 100, 100]) await esperar(ms);
console.log(`en fila: ${reloj()}`);
t0 = performance.now();
await Promise.all([100, 100, 100].map(esperar));
console.log(`juntos: ${reloj()}`);

