const esperar = ms => new Promise(r => setTimeout(r, ms));
async function consultar(patente) {
  await esperar(10);
  throw new Error(patente + ": sin señal");
}

// 1) Sin await: el try/catch termina antes de que la promesa falle
let promesa;
try {
  promesa = consultar("AB123CD");              // devuelve una promesa pendiente; no lanza nada todavía
  console.log("1) el try terminó sin ver ningún error");
} catch (e) {
  console.log("1) esto no se imprime nunca");
}
await promesa.catch(e => console.log("1) el error llegó por la promesa: " + e.message));

// 2) Con await: el rechazo vuelve a ser una excepción y el catch la atrapa
try {
  await consultar("EF456GH");
} catch (e) {
  console.log("2) con await, el catch atrapa: " + e.message);
}

// 3) Con .then(...).catch(...) el rechazo queda atendido y la cadena sigue con un valor de reemplazo
const resultado = await consultar("IJ789KL")
  .then(() => "bien")
  .catch(e => "valor de reemplazo (" + e.message + ")");
console.log("3) " + resultado);
